// Test real-time messaging with multiple clients
async function testRealTimeMessaging() {
  const userA = new MessengerClient('userA');
  const userB = new MessengerClient('userB');
  const userC = new MessengerClient('userC');

  // Connect all users
  await Promise.all([userA.connect(), userB.connect(), userC.connect()]);

  // User A starts typing
  await userA.startTyping('conversation123');

  // Verify typing indicator received by User B
  const typingEvent = await userB.waitForEvent('typing', 2000);
  expect(typingEvent.userId).toBe('userA');
  expect(typingEvent.conversationId).toBe('conversation123');

  // User A sends message
  const message1 = await userA.sendMessage('conversation123', 'Hello!');

  // Verify message received by User B
  const received1 = await userB.waitForEvent('message', 2000);
  expect(received1.content).toBe('Hello!');
  expect(received1.id).toBe(message1.id);

  // User B reads message
  await userB.markAsRead(message1.id);

  // Verify read receipt received by User A
  const receipt = await userA.waitForEvent('read_receipt', 2000);
  expect(receipt.messageId).toBe(message1.id);
  expect(receipt.readBy).toBe('userB');

  // Test group message
  await userA.sendMessage('conversation123', 'Group message', {
    recipients: ['userB', 'userC']
  });

  // Verify both users receive
  const [receivedB, receivedC] = await Promise.all([
    userB.waitForEvent('message', 2000),
    userC.waitForEvent('message', 2000)
  ]);

  expect(receivedB.content).toBe('Group message');
  expect(receivedC.content).toBe('Group message');

  // Test offline message delivery
  await userC.disconnect();
  await userA.sendMessage('conversation123', 'Offline message');
  await userC.connect();

  const offlineMessage = await userC.waitForEvent('message', 5000);
  expect(offlineMessage.content).toBe('Offline message');
}

// Social Media API Test Suite
const { test, expect } = require('@playwright/test');
const axios = require('axios');

// API configuration
const API_BASE = process.env.API_BASE || 'https://api.socialmedia.test';
const API_KEY = process.env.API_KEY;

// Helper functions
class SocialMediaAPI {
  constructor(token) {
    this.client = axios.create({
      baseURL: API_BASE,
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      }
    });
  }

  async createPost(data) {
    return this.client.post('/v1/posts', data);
  }

  async getPost(id) {
    return this.client.get(`/v1/posts/${id}`);
  }

  async likePost(postId) {
    return this.client.post(`/v1/posts/${postId}/like`);
  }

  async comment(postId, content) {
    return this.client.post(`/v1/posts/${postId}/comments`, { content });
  }

  async follow(userId) {
    return this.client.post(`/v1/users/${userId}/follow`);
  }

  async getFeed(params = {}) {
    return this.client.get('/v1/feed', { params });
  }
}

// Test suite
test.describe('Social Media API Tests', () => {
  let api;
  let testUser;
  let testPost;

  test.beforeAll(async () => {
    // Create test user and get token
    testUser = await createTestUser();
    api = new SocialMediaAPI(testUser.token);

    // Create a test post
    const response = await api.createPost({
      content: 'API Test Post',
      privacy: 'public'
    });
    testPost = response.data;
  });

