      mentions: ['user123'],
      location: {
        name: 'Test Location',
        coordinates: { lat: 40.7128, lng: -74.0060 }
      }
    };

    const response = await api.createPost(postData);

    expect(response.status).toBe(201);
    expect(response.data).toHaveProperty('id');
    expect(response.data.content).toBe(postData.content);
    expect(response.data.media).toHaveLength(2);
    expect(response.data.hashtags).toEqual(['test', 'api']);
  });

  test('Test feed pagination and sorting', async () => {
    // Create multiple posts for pagination test
    const posts = [];
    for (let i = 0; i < 15; i++) {
      const post = await api.createPost({
        content: `Test post ${i}`,
