        """Test automated content filtering"""
        test_content = [
            ('This is harmless content', 'should_allow'),
            ('Buy cheap viagra online!!!', 'should_block'),
            ('Hate speech targeting group', 'should_block'),
            ('Content with malicious http://phishing.site', 'should_block'),
            ('Legitimate http://example.com link', 'should_allow')
        ]

        user = self.create_test_user('mod_test_user')
        results = []

        for content, expected in test_content:
            response = self.create_post(user['token'], {
                'content': content,
                'privacy': 'public'
            })

            actual = 'blocked' if response.get('blocked') else 'allowed'
            passed = (actual == expected.replace('should_', ''))

            results.append({
                'content': content[:50] + '...' if len(content) > 50 else content,
                'expected': expected,
                'actual': actual,
                'passed': passed
            })

        passed_count = sum(1 for r in results if r['passed'])

        return {
            'status': 'passed' if passed_count == len(results) else 'failed',
            'accuracy': f'{passed_count}/{len(results)}',
            'details': results
        }

