        """Run comprehensive security assessment"""
        scan_results = {
            'timestamp': datetime.now().isoformat(),
            'authentication': self.test_authentication(),
            'authorization': self.test_authorization(self.admin_token),
            'data_privacy': self.test_data_privacy_compliance(),
            'content_moderation': self.test_content_moderation(),
            'api_security': self.test_api_security()
        }

        # Calculate overall score
        passed_tests = 0
        total_tests = 0

        for category, results in scan_results.items():
            if isinstance(results, dict) and 'status' in results:
                total_tests += 1
                if results['status'] == 'passed':
                    passed_tests += 1
            elif isinstance(results, dict):
                for test_name, test_result in results.items():
                    if isinstance(test_result, dict) and 'status' in test_result:
                        total_tests += 1
                        if test_result['status'] == 'passed':
                            passed_tests += 1

        scan_results['summary'] = {
            'total_tests': total_tests,
            'passed_tests': passed_tests,
            'failed_tests': total_tests - passed_tests,
            'score_percentage': (passed_tests / total_tests * 100) if total_tests > 0 else 0,
            'risk_level': self.calculate_risk_level(passed_tests, total_tests)
        }

        # Generate report
        self.generate_security_report(scan_results)

        return scan_results

    def calculate_risk_level(self, passed, total):
        """Calculate overall risk level"""
        percentage = (passed / total * 100) if total > 0 else 0

        if percentage >= 90:
            return 'LOW'
        elif percentage >= 70:
            return 'MEDIUM'
        else:
            return 'HIGH'

    def generate_security_report(self, results):
        """Generate security assessment report"""
        report = {
            'title': 'Social Media Platform Security Assessment',
            'date': datetime.now().strftime('%Y-%m-%d'),
            'summary': results['summary'],
            'detailed_findings': {},
            'recommendations': []
        }

        # Collect failed tests
        failed_tests = []
        for category, category_results in results.items():
            if category == 'summary':
                continue

            if isinstance(category_results, dict) and 'status' in category_results:
                if category_results['status'] == 'failed':
                    failed_tests.append({
                        'category': category,
                        'details': category_results
                    })
            elif isinstance(category_results, dict):
                for test_name, test_result in category_results.items():
                    if isinstance(test_result, dict) and test_result.get('status') == 'failed':
                        failed_tests.append({
                            'category': f'{category}.{test_name}',
                            'details': test_result
                        })

        report['detailed_findings']['failed_tests'] = failed_tests

        # Generate recommendations
        for failed in failed_tests:
            category = failed['category']
            details = failed['details']

            if 'authentication' in category:
                report['recommendations'].append(
                    'Strengthen authentication mechanisms and implement account lockout'
                )
            elif 'authorization' in category:
                report['recommendations'].append(
                    'Implement proper access controls and authorization checks'
                )
            elif 'privacy' in category:
                report['recommendations'].append(
                    'Enhance GDPR compliance and data privacy controls'
                )

        # Save report
        with open('security_assessment_report.json', 'w') as f:
            json.dump(report, f, indent=2)

        print(f"Security assessment complete. Score: {results['summary']['score_percentage']:.1f}%")
        print(f"Risk Level: {results['summary']['risk_level']}")
        print(f"Report saved to: security_assessment_report.json")

        return report

